const e=JSON.parse(`[{"id":"upsc-2017-prelims-gs1-a-051","year":2017,"stage":"Prelims","paper":"Prelims GS-I","number":51,"booklet":"A","questionType":"MCQ","subject":"History","topic":"Ancient India · kingdoms & rulers","question":"Which one of the following was a very important seaport in the Kakatiya kingdom?","options":{"a":"Kakinada","b":"Motupalli","c":"Machilipatnam (Masulipatnam)","d":"Nelluru"},"answer":"b","keyStatus":"official","marks":2,"negativeMarks":0.6666666666666666,"wordLimit":0,"sourceUrl":"https://www.minimalistias.com/pyqs/prelims/2017","keyUrl":"https://lotusarise.com/wp-content/uploads/2021/12/UPSC-Prelims-Official-Answer-Key-2017-GS-1.pdf#page=1","page":0,"blocks":[{"type":"paragraph","text":"Which one of the following was a very important seaport in the Kakatiya kingdom?"}],"sourceTitle":"UPSC CSE 2017 General Studies Paper I · Series A","explanation":{"justification":"Motupalli (situated in modern Krishna district of Andhra Pradesh) served as the primary and most prosperous international seaport of the Kakatiya dynasty, famously visited by Venetian traveler Marco Polo during the reign of Queen Rudrama Devi.","concept":"","references":[]},"sourceNotes":"Editorial study note matched by question wording and the final key’s correct-option wording; the UPSC final key controls scoring."},{"id":"upsc-2017-prelims-gs1-a-052","year":2017,"stage":"Prelims","paper":"Prelims GS-I","number":52,"booklet":"A","questionType":"MCQ","subject":"Environment","topic":"Climate action & agreements","question":"With reference to ‘Global Climate Change Alliance’, which of the following statements is/are correct?\\n\\n1. It is an initiative of the European Union.\\n2. It provides technical and financial support to targeted developing countries to integrate climate change into their development policies and budgets.\\n3. It is coordinated by World Resources Institute (WRI) and World Business Council for Sustainable Development (WBCSD).\\n\\nSelect the correct answer using the code given below:","options":{"a":"1 and 2 only","b":"3 only","c":"2 and 3 only","d":"1, 2 and 3"},"answer":"a","keyStatus":"official","marks":2,"negativeMarks":0.6666666666666666,"wordLimit":0,"sourceUrl":"https://www.minimalistias.com/pyqs/prelims/2017","keyUrl":"https://lotusarise.com/wp-content/uploads/2021/12/UPSC-Prelims-Official-Answer-Key-2017-GS-1.pdf#page=1","page":0,"blocks":[{"type":"paragraph","text":"With reference to ‘Global Climate Change Alliance’, which of the following statements is/are correct?"},{"type":"paragraph","text":"1. It is an initiative of the European Union.\\n2. It provides technical and financial support to targeted developing countries to integrate climate change into their development policies and budgets.\\n3. It is coordinated by World Resources Institute (WRI) and World Business Council for Sustainable Development (WBCSD)."},{"type":"paragraph","text":"Select the correct answer using the code given below:"}],"sourceTitle":"UPSC CSE 2017 General Studies Paper I · Series A","explanation":{"justification":"The Global Climate Change Alliance (GCCA) is an initiative of the European Union launched in 2007 to strengthen dialogue and cooperation on climate change with highly vulnerable developing countries (LDCs and SIDS), providing them with technical and financial support (Statements 1 and 2 are correct).  It is coordinated by the European Commission, not WRI and WBCSD (Statement 3 is incorrect).","concept":"","references":[]},"sourceNotes":"Editorial study note matched by question wording and the final key’s correct-option wording; the UPSC final key controls scoring."},{"id":"upsc-2017-prelims-gs1-a-053","year":2017,"stage":"Prelims","paper":"Prelims GS-I","number":53,"booklet":"A","questionType":"MCQ","subject":"Art & Culture","topic":"Religion & philosophical traditions","question":"With reference to the religious history of India, consider the following statements:\\n\\n1. Sautrantika and Sammitiya were the sects of Jainism.\\n2. Sarvastivadin held that the constituents of phenomena were not wholly momentary, but existed forever in a latent form.\\n\\nWhich of the statements given above is/are correct?","options":{"a":"1 only","b":"2 only","c":"Both 1 and 2","d":"Neither 1 nor 2"},"answer":"b","keyStatus":"official","marks":2,"negativeMarks":0.6666666666666666,"wordLimit":0,"sourceUrl":"https://www.minimalistias.com/pyqs/prelims/2017","keyUrl":"https://lotusarise.com/wp-content/uploads/2021/12/UPSC-Prelims-Official-Answer-Key-2017-GS-1.pdf#page=1","page":0,"blocks":[{"type":"paragraph","text":"With reference to the religious history of India, consider the following statements:"},{"type":"paragraph","text":"1. Sautrantika and Sammitiya were the sects of Jainism.\\n2. Sarvastivadin held that the constituents of phenomena were not wholly momentary, but existed forever in a latent form."},{"type":"paragraph","text":"Which of the statements given above is/are correct?"}],"sourceTitle":"UPSC CSE 2017 General Studies Paper I · Series A","explanation":{"justification":"Statement 1 is incorrect as Sautrantika and Sammitiya are ancient sects of Buddhism, not Jainism. Statement 2 is correct because the Sarvastivadin sect of early Buddhism believed that all things exist continuously, in the past, present, and future in a latent form.","concept":"","references":[]},"sourceNotes":"Editorial study note matched by question wording and the final key’s correct-option wording; the UPSC final key controls scoring."},{"id":"upsc-2017-prelims-gs1-a-054","year":2017,"stage":"Prelims","paper":"Prelims GS-I","number":54,"booklet":"A","questionType":"MCQ","subject":"Geography","topic":"World geography & mapping","question":"Mediterranean Sea is a border of which of the following countries?\\n\\n1. Jordan\\n2. Iraq\\n3. Lebanon\\n4. Syria\\n\\nSelect the correct answer using the code given below:","options":{"a":"1, 2 and 3 only","b":"2 and 3 only","c":"3 and 4 only","d":"1, 3 and 4 only"},"answer":"c","keyStatus":"official","marks":2,"negativeMarks":0.6666666666666666,"wordLimit":0,"sourceUrl":"https://www.minimalistias.com/pyqs/prelims/2017","keyUrl":"https://lotusarise.com/wp-content/uploads/2021/12/UPSC-Prelims-Official-Answer-Key-2017-GS-1.pdf#page=1","page":0,"blocks":[{"type":"paragraph","text":"Mediterranean Sea is a border of which of the following countries?"},{"type":"paragraph","text":"1. Jordan\\n2. Iraq\\n3. Lebanon\\n4. Syria"},{"type":"paragraph","text":"Select the correct answer using the code given below:"}],"sourceTitle":"UPSC CSE 2017 General Studies Paper I · Series A","explanation":{"justification":"Option 1 is incorrect. Jordan is bounded to the north by Syria, to the east by Iraq, to the southeast and south by Saudi Arabia, and to the west by Israel and the West Bank. It opens into the Red Sea at its southern most point. Option 2 is incorrect. Iraq is bordered to the north by Turkey, to the east by Iran, to the west by Syria and Jordan, and to the south by Saudi Arabia and Kuwait. It has access to Persian Gulf in the South Option 3 and 4 are correct. Following countries have a shoreline at the Mediterranean Sea: European countries: Spain, France, Italy, Malta, Monaco, Slovenia, Croatia, Bosnia and Herzegovina, Montenegro, Albania, and Greece. Western Asia (Middle East): Turkey, Cyprus, Syria, Lebanon, Israel, and the Palestine Gaza Strip. 21 countries including Albania, Algeria, Bosnia and Herzegovina, Croatia, Cyprus, Egypt, France, Greece, Israel, Italy, Lebanon, Libya, Malta, Monaco, Montenegro, Morocco, Slovenia, Spain, Syria, Tunisia, and Turkey share their border with Mediterranean Sea.","concept":"","references":[]},"sourceNotes":"Editorial study note matched by question wording and the final key’s correct-option wording; the UPSC final key controls scoring."},{"id":"upsc-2017-prelims-gs1-a-055","year":2017,"stage":"Prelims","paper":"Prelims GS-I","number":55,"booklet":"A","questionType":"MCQ","subject":"Economy","topic":"Infrastructure investment","question":"With reference to ‘National Investment and Infrastructure Fund’, which of the following statements is/are correct?\\n\\n1. It is an organ of NITI Aayog.\\n2. It has a corpus of ₹ 4,00,000 crore at present.\\n\\nSelect the correct answer using the code given below:","options":{"a":"1 only","b":"2 only","c":"Both 1 and 2","d":"Neither 1 nor 2"},"answer":"d","keyStatus":"official","marks":2,"negativeMarks":0.6666666666666666,"wordLimit":0,"sourceUrl":"https://www.minimalistias.com/pyqs/prelims/2017","keyUrl":"https://lotusarise.com/wp-content/uploads/2021/12/UPSC-Prelims-Official-Answer-Key-2017-GS-1.pdf#page=1","page":0,"blocks":[{"type":"paragraph","text":"With reference to ‘National Investment and Infrastructure Fund’, which of the following statements is/are correct?"},{"type":"paragraph","text":"1. It is an organ of NITI Aayog.\\n2. It has a corpus of ₹ 4,00,000 crore at present."},{"type":"paragraph","text":"Select the correct answer using the code given below:"}],"sourceTitle":"UPSC CSE 2017 General Studies Paper I · Series A","explanation":{"justification":"NIIF was established as an investment vehicle under the Government’s finance framework, not as a NITI Aayog organ. The announced corpus was₹ 40,000 crore, not₹ 4,00,000 crore. Neither statement is correct.","concept":"Infrastructure investment","references":[{"title":"UPSC CSE2017 final key · SeriesA","url":"https://lotusarise.com/wp-content/uploads/2021/12/UPSC-Prelims-Official-Answer-Key-2017-GS-1.pdf#page=1"}]},"sourceNotes":"Editorial study note checked against the final key’s correct option; UPSC publishes the answer key, not these explanations."},{"id":"upsc-2017-prelims-gs1-a-056","year":2017,"stage":"Prelims","paper":"Prelims GS-I","number":56,"booklet":"A","questionType":"MCQ","subject":"Economy","topic":"Global Infrastructure Facility","question":"The Global Infrastructure Facility is a/an","options":{"a":"ASEAN initiative to upgrade infrastructure in Asia and financed by credit from the Asian Development Bank.","b":"World Bank collaboration that facilitates the preparation and structuring of complex infrastructure Public-Private Partnerships (PPPs) to enable mobilization of private sector and institutional investor capital.","c":"Collaboration among the major banks of the world working with the OECD and focused on expanding the set of infrastructure projects that have the potential to mobilize private investment.","d":"UNCTAD funded initiative that seeks to finance and facilitate infrastructure development in the world."},"answer":"b","keyStatus":"official","marks":2,"negativeMarks":0.6666666666666666,"wordLimit":0,"sourceUrl":"https://www.minimalistias.com/pyqs/prelims/2017","keyUrl":"https://lotusarise.com/wp-content/uploads/2021/12/UPSC-Prelims-Official-Answer-Key-2017-GS-1.pdf#page=1","page":0,"blocks":[{"type":"paragraph","text":"The Global Infrastructure Facility is a/an"}],"sourceTitle":"UPSC CSE 2017 General Studies Paper I · Series A","explanation":{"justification":"The Global Infrastructure Facility is a World Bank collaboration that helps prepare and structure complex public-private infrastructure projects so they can attract private and institutional investment.","concept":"Global Infrastructure Facility","references":[{"title":"UPSC CSE2017 final key · SeriesA","url":"https://lotusarise.com/wp-content/uploads/2021/12/UPSC-Prelims-Official-Answer-Key-2017-GS-1.pdf#page=1"}]},"sourceNotes":"Editorial study note checked against the final key’s correct option; UPSC publishes the answer key, not these explanations."},{"id":"upsc-2017-prelims-gs1-a-057","year":2017,"stage":"Prelims","paper":"Prelims GS-I","number":57,"booklet":"A","questionType":"MCQ","subject":"Polity & Governance","topic":"Organisations & miscellaneous polity","question":"For election to the Lok Sabha, a nomination paper can be filed by","options":{"a":"anyone residing in India.","b":"a resident of the constituency from which the election is to be contested.","c":"any citizen of India whose name appears in the electoral roll of a constituency.","d":"any citizen of India."},"answer":"c","keyStatus":"official","marks":2,"negativeMarks":0.6666666666666666,"wordLimit":0,"sourceUrl":"https://www.minimalistias.com/pyqs/prelims/2017","keyUrl":"https://lotusarise.com/wp-content/uploads/2021/12/UPSC-Prelims-Official-Answer-Key-2017-GS-1.pdf#page=1","page":0,"blocks":[{"type":"paragraph","text":"For election to the Lok Sabha, a nomination paper can be filed by"}],"sourceTitle":"UPSC CSE 2017 General Studies Paper I · Series A","explanation":{"justification":"According to the Representation of People Act, 1951, a candidate for the Lok Sabha must be registered as an elector for a parliamentary constituency (their name must appear in the electoral roll).","concept":"","references":[]},"sourceNotes":"Editorial study note matched by question wording and the final key’s correct-option wording; the UPSC final key controls scoring."},{"id":"upsc-2017-prelims-gs1-a-058","year":2017,"stage":"Prelims","paper":"Prelims GS-I","number":58,"booklet":"A","questionType":"MCQ","subject":"Geography","topic":"Extent of physical features","question":"Consider the following statements:\\n\\n1. In India, the Himalayas are spread over five States only.\\n2. Western Ghats are spread over five States only.\\n3. Pulicat Lake is spread over two States only.\\n\\nWhich of the statements given above is/are correct?","options":{"a":"1 and 2 only","b":"3 only","c":"2 and 3 only","d":"1 and 3 only"},"answer":"b","keyStatus":"official","marks":2,"negativeMarks":0.6666666666666666,"wordLimit":0,"sourceUrl":"https://www.minimalistias.com/pyqs/prelims/2017","keyUrl":"https://lotusarise.com/wp-content/uploads/2021/12/UPSC-Prelims-Official-Answer-Key-2017-GS-1.pdf#page=1","page":0,"blocks":[{"type":"paragraph","text":"Consider the following statements:"},{"type":"paragraph","text":"1. In India, the Himalayas are spread over five States only.\\n2. Western Ghats are spread over five States only.\\n3. Pulicat Lake is spread over two States only."},{"type":"paragraph","text":"Which of the statements given above is/are correct?"}],"sourceTitle":"UPSC CSE 2017 General Studies Paper I · Series A","explanation":{"justification":"The Himalayas extend across more than five Indian States, and the Western Ghats extend across six States. Pulicat Lake spans Andhra Pradesh and Tamil Nadu. Only statement 3 is correct.","concept":"Extent of physical features","references":[{"title":"UPSC CSE2017 final key · SeriesA","url":"https://lotusarise.com/wp-content/uploads/2021/12/UPSC-Prelims-Official-Answer-Key-2017-GS-1.pdf#page=1"}]},"sourceNotes":"Editorial study note checked against the final key’s correct option; UPSC publishes the answer key, not these explanations."},{"id":"upsc-2017-prelims-gs1-a-059","year":2017,"stage":"Prelims","paper":"Prelims GS-I","number":59,"booklet":"A","questionType":"MCQ","subject":"Environment","topic":"Ecology & environment","question":"Biological Oxygen Demand (BOD) is a standard criterion for","options":{"a":"Measuring oxygen levels in blood","b":"Computing oxygen levels in forest ecosystems","c":"Pollution assay in aquatic ecosystems","d":"Assessing oxygen levels in high altitude regions"},"answer":"c","keyStatus":"official","marks":2,"negativeMarks":0.6666666666666666,"wordLimit":0,"sourceUrl":"https://www.minimalistias.com/pyqs/prelims/2017","keyUrl":"https://lotusarise.com/wp-content/uploads/2021/12/UPSC-Prelims-Official-Answer-Key-2017-GS-1.pdf#page=1","page":0,"blocks":[{"type":"paragraph","text":"Biological Oxygen Demand (BOD) is a standard criterion for"}],"sourceTitle":"UPSC CSE 2017 General Studies Paper I · Series A","explanation":{"justification":"Biological Oxygen Demand (BOD) is the amount of dissolved oxygen needed by aerobic micro-organisms to break down organic material in a water sample. It is a standard criterion for measuring pollution levels in aquatic ecosystems.","concept":"","references":[]},"sourceNotes":"Editorial study note matched by question wording and the final key’s correct-option wording; the UPSC final key controls scoring."},{"id":"upsc-2017-prelims-gs1-a-060","year":2017,"stage":"Prelims","paper":"Prelims GS-I","number":60,"booklet":"A","questionType":"MCQ","subject":"International Relations","topic":"UN-Habitat","question":"With reference to the role of UN-Habitat in the United Nations programme working towards a better urban future, which of the statements is/are correct?\\n\\n1. UN-Habitat has been mandated by the United Nations General Assembly to promote socially and environmentally sustainable towns and cities to provide adequate shelter for all.\\n2. Its partners are either governments or local urban authorities only.\\n3. UN-Habitat contributes to the overall objective of the United Nations system to reduce poverty and to promote access to safe drinking water and basic sanitation.\\n\\nSelect the correct answer using the code given below:","options":{"a":"1, 2 and 3","b":"1 and 3 only","c":"2 and 3 only","d":"1 only"},"answer":"b","keyStatus":"official","marks":2,"negativeMarks":0.6666666666666666,"wordLimit":0,"sourceUrl":"https://www.minimalistias.com/pyqs/prelims/2017","keyUrl":"https://lotusarise.com/wp-content/uploads/2021/12/UPSC-Prelims-Official-Answer-Key-2017-GS-1.pdf#page=1","page":0,"blocks":[{"type":"paragraph","text":"With reference to the role of UN-Habitat in the United Nations programme working towards a better urban future, which of the statements is/are correct?"},{"type":"paragraph","text":"1. UN-Habitat has been mandated by the United Nations General Assembly to promote socially and environmentally sustainable towns and cities to provide adequate shelter for all.\\n2. Its partners are either governments or local urban authorities only.\\n3. UN-Habitat contributes to the overall objective of the United Nations system to reduce poverty and to promote access to safe drinking water and basic sanitation."},{"type":"paragraph","text":"Select the correct answer using the code given below:"}],"sourceTitle":"UPSC CSE 2017 General Studies Paper I · Series A","explanation":{"justification":"UN-Habitat promotes sustainable settlements, adequate shelter and access to services including water and sanitation. Its partnerships also include civil society, academia and private organisations, so they are not restricted to governments.","concept":"UN-Habitat","references":[{"title":"UPSC CSE2017 final key · SeriesA","url":"https://lotusarise.com/wp-content/uploads/2021/12/UPSC-Prelims-Official-Answer-Key-2017-GS-1.pdf#page=1"}]},"sourceNotes":"Editorial study note checked against the final key’s correct option; UPSC publishes the answer key, not these explanations."},{"id":"upsc-2017-prelims-gs1-a-061","year":2017,"stage":"Prelims","paper":"Prelims GS-I","number":61,"booklet":"A","questionType":"MCQ","subject":"Social Development","topic":"National Skills Qualification Framework","question":"With reference to ‘National Skills Qualification Framework (NSQF)’, which of the statements given below is/are correct?\\n\\n1. Under NSQF, a learner can acquire the certification for competency only through formal learning.\\n2. An outcome expected from the implementation of NSQF is the mobility between vocational and general education.\\n\\nSelect the correct answer using the code given below:","options":{"a":"1 only","b":"2 only","c":"Both 1 and 2","d":"Neither 1 nor 2"},"answer":"b","keyStatus":"official","marks":2,"negativeMarks":0.6666666666666666,"wordLimit":0,"sourceUrl":"https://www.minimalistias.com/pyqs/prelims/2017","keyUrl":"https://lotusarise.com/wp-content/uploads/2021/12/UPSC-Prelims-Official-Answer-Key-2017-GS-1.pdf#page=1","page":0,"blocks":[{"type":"paragraph","text":"With reference to ‘National Skills Qualification Framework (NSQF)’, which of the statements given below is/are correct?"},{"type":"paragraph","text":"1. Under NSQF, a learner can acquire the certification for competency only through formal learning.\\n2. An outcome expected from the implementation of NSQF is the mobility between vocational and general education."},{"type":"paragraph","text":"Select the correct answer using the code given below:"}],"sourceTitle":"UPSC CSE 2017 General Studies Paper I · Series A","explanation":{"justification":"NSQF recognises competency gained through formal, non-formal and informal learning. It also supports movement between vocational and general education. Only statement 2 is correct.","concept":"National Skills Qualification Framework","references":[{"title":"UPSC CSE2017 final key · SeriesA","url":"https://lotusarise.com/wp-content/uploads/2021/12/UPSC-Prelims-Official-Answer-Key-2017-GS-1.pdf#page=1"}]},"sourceNotes":"Editorial study note checked against the final key’s correct option; UPSC publishes the answer key, not these explanations."},{"id":"upsc-2017-prelims-gs1-a-062","year":2017,"stage":"Prelims","paper":"Prelims GS-I","number":62,"booklet":"A","questionType":"MCQ","subject":"History","topic":"Modern India · Gandhian & mass movements","question":"In the context of Indian history, the principle of ‘Dyarchy (diarchy)’ refers to","options":{"a":"Division of the central legislature into two houses.","b":"Introduction of double government i.e., Central and State governments.","c":"Having two sets of rulers; one in London and another in Delhi.","d":"Division of the subjects delegated to the provinces into two categories."},"answer":"d","keyStatus":"official","marks":2,"negativeMarks":0.6666666666666666,"wordLimit":0,"sourceUrl":"https://www.minimalistias.com/pyqs/prelims/2017","keyUrl":"https://lotusarise.com/wp-content/uploads/2021/12/UPSC-Prelims-Official-Answer-Key-2017-GS-1.pdf#page=1","page":0,"blocks":[{"type":"paragraph","text":"In the context of Indian history, the principle of ‘Dyarchy (diarchy)’ refers to"}],"sourceTitle":"UPSC CSE 2017 General Studies Paper I · Series A","explanation":{"justification":"Introduced by the Government of India Act 1919, 'Dyarchy' meant the rule of two at the provincial executive level, where provincial subjects were divided into two categories: 'transferred' and 'reserved'.","concept":"","references":[]},"sourceNotes":"Editorial study note matched by question wording and the final key’s correct-option wording; the UPSC final key controls scoring."},{"id":"upsc-2017-prelims-gs1-a-063","year":2017,"stage":"Prelims","paper":"Prelims GS-I","number":63,"booklet":"A","questionType":"MCQ","subject":"Social Development","topic":"National Career Service","question":"Consider the following in respect of ‘National Career Service’:\\n\\n1. National Career Service is an initiative of the Department of Personnel and Training, Government of India.\\n2. National Career Service has been launched in a Mission Mode to improve the employment opportunities to uneducated youth of the country.\\n\\nWhich of the above statements is/are correct?","options":{"a":"1 only","b":"2 only","c":"Both 1 and 2","d":"Neither 1 nor 2"},"answer":"d","keyStatus":"official","marks":2,"negativeMarks":0.6666666666666666,"wordLimit":0,"sourceUrl":"https://www.minimalistias.com/pyqs/prelims/2017","keyUrl":"https://lotusarise.com/wp-content/uploads/2021/12/UPSC-Prelims-Official-Answer-Key-2017-GS-1.pdf#page=1","page":0,"blocks":[{"type":"paragraph","text":"Consider the following in respect of ‘National Career Service’:"},{"type":"paragraph","text":"1. National Career Service is an initiative of the Department of Personnel and Training, Government of India.\\n2. National Career Service has been launched in a Mission Mode to improve the employment opportunities to uneducated youth of the country."},{"type":"paragraph","text":"Which of the above statements is/are correct?"}],"sourceTitle":"UPSC CSE 2017 General Studies Paper I · Series A","explanation":{"justification":"National Career Service is a Ministry of Labour and Employment initiative. It serves jobseekers across educational and skill levels, not only uneducated youth. Both stated descriptions are incorrect.","concept":"National Career Service","references":[{"title":"UPSC CSE2017 final key · SeriesA","url":"https://lotusarise.com/wp-content/uploads/2021/12/UPSC-Prelims-Official-Answer-Key-2017-GS-1.pdf#page=1"}]},"sourceNotes":"Editorial study note checked against the final key’s correct option; UPSC publishes the answer key, not these explanations."},{"id":"upsc-2017-prelims-gs1-a-064","year":2017,"stage":"Prelims","paper":"Prelims GS-I","number":64,"booklet":"A","questionType":"MCQ","subject":"Economy","topic":"Stressed-asset restructuring","question":"Which of the following statements best describes the term ‘Scheme for Sustainable Structuring of Stressed Assets (S4A)’, recently seen in the news?","options":{"a":"It is a procedure for considering ecological costs of developmental schemes formulated by the Government.","b":"It is a scheme of RBI for reworking the financial structure of big corporate entities facing genuine difficulties.","c":"It is a disinvestment plan of the Government regarding Central Public Sector Undertakings.","d":"It is an important provision in ‘The Insolvency and Bankruptcy Code’ recently implemented by the Government."},"answer":"b","keyStatus":"official","marks":2,"negativeMarks":0.6666666666666666,"wordLimit":0,"sourceUrl":"https://www.minimalistias.com/pyqs/prelims/2017","keyUrl":"https://lotusarise.com/wp-content/uploads/2021/12/UPSC-Prelims-Official-Answer-Key-2017-GS-1.pdf#page=1","page":0,"blocks":[{"type":"paragraph","text":"Which of the following statements best describes the term ‘Scheme for Sustainable Structuring of Stressed Assets (S4A)’, recently seen in the news?"}],"sourceTitle":"UPSC CSE 2017 General Studies Paper I · Series A","explanation":{"justification":"RBI’s S 4 A framework sought to separate sustainable and unsustainable debt for large stressed corporate borrowers, allowing financial restructuring where projects remained viable.","concept":"Stressed-asset restructuring","references":[{"title":"UPSC CSE2017 final key · SeriesA","url":"https://lotusarise.com/wp-content/uploads/2021/12/UPSC-Prelims-Official-Answer-Key-2017-GS-1.pdf#page=1"}]},"sourceNotes":"Editorial study note checked against the final key’s correct option; UPSC publishes the answer key, not these explanations."},{"id":"upsc-2017-prelims-gs1-a-065","year":2017,"stage":"Prelims","paper":"Prelims GS-I","number":65,"booklet":"A","questionType":"MCQ","subject":"Environment","topic":"Climate action & agreements","question":"Consider the following statements:\\n\\n1. Climate and Clean Air Coalition (CCAC) to Reduce Short Lived Climate Pollutants is a unique initiative of G20 group of countries.\\n2. The CCAC focuses on methane, black carbon and hydrofluorocarbons.\\n\\nWhich of the statements given above is/are correct?","options":{"a":"1 only","b":"2 only","c":"Both 1 and 2","d":"Neither 1 nor 2"},"answer":"b","keyStatus":"official","marks":2,"negativeMarks":0.6666666666666666,"wordLimit":0,"sourceUrl":"https://www.minimalistias.com/pyqs/prelims/2017","keyUrl":"https://lotusarise.com/wp-content/uploads/2021/12/UPSC-Prelims-Official-Answer-Key-2017-GS-1.pdf#page=1","page":0,"blocks":[{"type":"paragraph","text":"Consider the following statements:"},{"type":"paragraph","text":"1. Climate and Clean Air Coalition (CCAC) to Reduce Short Lived Climate Pollutants is a unique initiative of G20 group of countries.\\n2. The CCAC focuses on methane, black carbon and hydrofluorocarbons."},{"type":"paragraph","text":"Which of the statements given above is/are correct?"}],"sourceTitle":"UPSC CSE 2017 General Studies Paper I · Series A","explanation":{"justification":"The CCAC was launched by the United Nations Environment Programme (UNEP) and six countries (Bangladesh, Canada, Ghana, Mexico, Sweden, and the US), not the G20 (Statement 1 is incorrect).  Its primary focus is indeed to reduce short-lived climate pollutants like methane, black carbon, and hydrofluorocarbons (HFCs) (Statement 2 is correct).","concept":"","references":[]},"sourceNotes":"Editorial study note matched by question wording and the final key’s correct-option wording; the UPSC final key controls scoring."},{"id":"upsc-2017-prelims-gs1-a-066","year":2017,"stage":"Prelims","paper":"Prelims GS-I","number":66,"booklet":"A","questionType":"MCQ","subject":"Geography","topic":"India Physical Environment","question":"With reference to ‘Indian Ocean Dipole (IOD)’ sometimes mentioned in the news while forecasting Indian monsoon, which of the following statements is/are correct?\\n\\n1. IOD phenomenon is characterised by a difference in sea surface temperature between tropical Western Indian Ocean and tropical Eastern Pacific Ocean.\\n2. An IOD phenomenon can influence an El Nino’s impact on the monsoon.\\n\\nSelect the correct answer using the code given below:","options":{"a":"1 only","b":"2 only","c":"Both 1 and 2","d":"Neither 1 nor 2"},"answer":"b","keyStatus":"official","marks":2,"negativeMarks":0.6666666666666666,"wordLimit":0,"sourceUrl":"https://www.minimalistias.com/pyqs/prelims/2017","keyUrl":"https://lotusarise.com/wp-content/uploads/2021/12/UPSC-Prelims-Official-Answer-Key-2017-GS-1.pdf#page=1","page":0,"blocks":[{"type":"paragraph","text":"With reference to ‘Indian Ocean Dipole (IOD)’ sometimes mentioned in the news while forecasting Indian monsoon, which of the following statements is/are correct?"},{"type":"paragraph","text":"1. IOD phenomenon is characterised by a difference in sea surface temperature between tropical Western Indian Ocean and tropical Eastern Pacific Ocean.\\n2. An IOD phenomenon can influence an El Nino’s impact on the monsoon."},{"type":"paragraph","text":"Select the correct answer using the code given below:"}],"sourceTitle":"UPSC CSE 2017 General Studies Paper I · Series A","explanation":{"justification":"Statement 1 is incorrect. The Indian Ocean Dipole - often called the “Indian Niño” because of its similarity to its Pacific equivalent - refers to the difference in sea-surface temperatures in opposite parts of the Indian Ocean. Temperatures in the eastern part of the Indian Ocean oscillate between warm and cold compared with the western part, cycling through phases referred to as “positive”, “neutral” and “negative”. The dipole’s positive phase this year means warmer sea temperatures in the western Indian Ocean region, with the opposite in the east. The result of this may be higher-than-average rainfall and floods in eastern Africa and droughts in south-east Asia and Australia. During a negative IOD, the opposite happens, that is, the western Indian Ocean becomes cooler with higher air pressures resulting in westerly winds blowing toward the Indian subcontinent. Statement 2 is correct. The Indian Ocean Dipole (IOD) is the Indian Ocean counterpartof the Pacific El Niño and La Niña. Like ENSO, IOD isa coupled ocean-atmosphere phenomenon. The shifting pools of warm/cool water contribute to variations in rainfall and storm activities of many countries surrounding the Indian Ocean. Positive IODs are often associated with El Niño and negative IODs with La Niña. A positive IOD leads to greater monsoon rainfall and more active (above normal rainfall). monsoon days while negative IOD leads to less rainfall and more monsoon break days (no rainfall).","concept":"India Physical Environment","references":[]},"sourceNotes":"Editorial study note matched by question wording and the final key’s correct-option wording; the UPSC final key controls scoring."},{"id":"upsc-2017-prelims-gs1-a-067","year":2017,"stage":"Prelims","paper":"Prelims GS-I","number":67,"booklet":"A","questionType":"MCQ","subject":"Environment","topic":"Biodiversity & conservation","question":"If you want to see gharials in their natural habitat, which one of the following is the best place to visit?","options":{"a":"Bhitarkanika Mangroves","b":"Chambal River","c":"Pulicat Lake","d":"Deepor Beel"},"answer":"b","keyStatus":"official","marks":2,"negativeMarks":0.6666666666666666,"wordLimit":0,"sourceUrl":"https://www.minimalistias.com/pyqs/prelims/2017","keyUrl":"https://lotusarise.com/wp-content/uploads/2021/12/UPSC-Prelims-Official-Answer-Key-2017-GS-1.pdf#page=1","page":0,"blocks":[{"type":"paragraph","text":"If you want to see gharials in their natural habitat, which one of the following is the best place to visit?"}],"sourceTitle":"UPSC CSE 2017 General Studies Paper I · Series A","explanation":{"justification":"The National Chambal Sanctuary, located along the Chambal River, is the primary and best natural habitat in India dedicated to the protection of the critically endangered Gharial crocodile.","concept":"","references":[]},"sourceNotes":"Editorial study note matched by question wording and the final key’s correct-option wording; the UPSC final key controls scoring."},{"id":"upsc-2017-prelims-gs1-a-068","year":2017,"stage":"Prelims","paper":"Prelims GS-I","number":68,"booklet":"A","questionType":"MCQ","subject":"Science & Technology","topic":"Applied science & technology","question":"Consider the following in respect of Indian Ocean Naval Symposium (IONS):\\n\\n1. Inaugural IONS was held in India in 2015 under the chairmanship of the Indian Navy.\\n2. IONS is a voluntary initiative that seeks to increase maritime co-operation among navies of the littoral states of the Indian Ocean Region.\\n\\nWhich of the above statements is/are correct?","options":{"a":"1 only","b":"2 only","c":"Both 1 and 2","d":"Neither 1 nor 2"},"answer":"b","keyStatus":"official","marks":2,"negativeMarks":0.6666666666666666,"wordLimit":0,"sourceUrl":"https://www.minimalistias.com/pyqs/prelims/2017","keyUrl":"https://lotusarise.com/wp-content/uploads/2021/12/UPSC-Prelims-Official-Answer-Key-2017-GS-1.pdf#page=1","page":0,"blocks":[{"type":"paragraph","text":"Consider the following in respect of Indian Ocean Naval Symposium (IONS):"},{"type":"paragraph","text":"1. Inaugural IONS was held in India in 2015 under the chairmanship of the Indian Navy.\\n2. IONS is a voluntary initiative that seeks to increase maritime co-operation among navies of the littoral states of the Indian Ocean Region."},{"type":"paragraph","text":"Which of the above statements is/are correct?"}],"sourceTitle":"UPSC CSE 2017 General Studies Paper I · Series A","explanation":{"justification":"The inaugural IONS was held in 2008 (not 2015), making statement 1 incorrect. IONS is indeed a voluntary initiative bringing together the navies of the littoral states of the Indian Ocean Region to increase maritime cooperation.","concept":"","references":[]},"sourceNotes":"Editorial study note matched by question wording and the final key’s correct-option wording; the UPSC final key controls scoring."},{"id":"upsc-2017-prelims-gs1-a-069","year":2017,"stage":"Prelims","paper":"Prelims GS-I","number":69,"booklet":"A","questionType":"MCQ","subject":"Art & Culture","topic":"Art, architecture & monuments","question":"The painting of Bodhisattva Padmapani is one of the most famous and oft-illustrated paintings at","options":{"a":"Ajanta","b":"Badami","c":"Bagh","d":"Ellora"},"answer":"a","keyStatus":"official","marks":2,"negativeMarks":0.6666666666666666,"wordLimit":0,"sourceUrl":"https://www.minimalistias.com/pyqs/prelims/2017","keyUrl":"https://lotusarise.com/wp-content/uploads/2021/12/UPSC-Prelims-Official-Answer-Key-2017-GS-1.pdf#page=1","page":0,"blocks":[{"type":"paragraph","text":"The painting of Bodhisattva Padmapani is one of the most famous and oft-illustrated paintings at"}],"sourceTitle":"UPSC CSE 2017 General Studies Paper I · Series A","explanation":{"justification":"The world-famous mural painting of Bodhisattva Padmapani, holding a blue lotus with an expression of deep peace and compassion, is preserved on the wall of Cave No. 1 at the Ajanta Caves in Maharashtra.","concept":"","references":[]},"sourceNotes":"Editorial study note matched by question wording and the final key’s correct-option wording; the UPSC final key controls scoring."},{"id":"upsc-2017-prelims-gs1-a-070","year":2017,"stage":"Prelims","paper":"Prelims GS-I","number":70,"booklet":"A","questionType":"MCQ","subject":"Art & Culture","topic":"Community festivals","question":"Consider the following pairs:\\n\\n | Traditions | Communities\\n1. | Chaliha Sahib Festival | Sindhis\\n2. | Nanda Raj Jaat Yatra | Gonds\\n3. | Wari-Warkari | Santhals\\n\\nWhich of the pairs given above is/are correctly matched?","options":{"a":"1 only","b":"2 and 3 only","c":"1 and 3 only","d":"None of the above"},"answer":"a","keyStatus":"official","marks":2,"negativeMarks":0.6666666666666666,"wordLimit":0,"sourceUrl":"https://www.minimalistias.com/pyqs/prelims/2017","keyUrl":"https://lotusarise.com/wp-content/uploads/2021/12/UPSC-Prelims-Official-Answer-Key-2017-GS-1.pdf#page=1","page":0,"blocks":[{"type":"paragraph","text":"Consider the following pairs:"},{"type":"table","headers":["No.","Traditions","Communities"],"rows":[["1.","Chaliha Sahib Festival","Sindhis"],["2.","Nanda Raj Jaat Yatra","Gonds"],["3.","Wari-Warkari","Santhals"]]},{"type":"paragraph","text":"Which of the pairs given above is/are correctly matched?"}],"sourceTitle":"UPSC CSE 2017 General Studies Paper I · Series A","explanation":{"justification":"Chaliha Sahib is associated with Sindhis. Nanda Raj Jaat belongs to Uttarakhand’s Himalayan traditions, while Wari-Warkari is associated with Maharashtra. Only pair 1 is correct.","concept":"Community festivals","references":[{"title":"UPSC CSE2017 final key · SeriesA","url":"https://lotusarise.com/wp-content/uploads/2021/12/UPSC-Prelims-Official-Answer-Key-2017-GS-1.pdf#page=1"}]},"sourceNotes":"Editorial study note checked against the final key’s correct option; UPSC publishes the answer key, not these explanations."},{"id":"upsc-2017-prelims-gs1-a-071","year":2017,"stage":"Prelims","paper":"Prelims GS-I","number":71,"booklet":"A","questionType":"MCQ","subject":"Economy","topic":"Water conservation in agriculture","question":"Which of the following practices can help in water conservation in agriculture?\\n\\n1. Reduced or zero tillage of the land\\n2. Applying gypsum before irrigating the field\\n3. Allowing crop residue to remain in the field\\n\\nSelect the correct answer using the code given below:","options":{"a":"1 and 2 only","b":"3 only","c":"1 and 3 only","d":"1, 2 and 3"},"answer":"c","keyStatus":"official","marks":2,"negativeMarks":0.6666666666666666,"wordLimit":0,"sourceUrl":"https://www.minimalistias.com/pyqs/prelims/2017","keyUrl":"https://lotusarise.com/wp-content/uploads/2021/12/UPSC-Prelims-Official-Answer-Key-2017-GS-1.pdf#page=1","page":0,"blocks":[{"type":"paragraph","text":"Which of the following practices can help in water conservation in agriculture?"},{"type":"paragraph","text":"1. Reduced or zero tillage of the land\\n2. Applying gypsum before irrigating the field\\n3. Allowing crop residue to remain in the field"},{"type":"paragraph","text":"Select the correct answer using the code given below:"}],"sourceTitle":"UPSC CSE 2017 General Studies Paper I · Series A","explanation":{"justification":"Reduced tillage and leaving crop residue on the surface conserve soil moisture. Gypsum is mainly used to ameliorate sodic soils, rather than being a general water-conservation practice. Items 1 and 3 are selected.","concept":"Water conservation in agriculture","references":[{"title":"UPSC CSE2017 final key · SeriesA","url":"https://lotusarise.com/wp-content/uploads/2021/12/UPSC-Prelims-Official-Answer-Key-2017-GS-1.pdf#page=1"}]},"sourceNotes":"Editorial study note checked against the final key’s correct option; UPSC publishes the answer key, not these explanations."},{"id":"upsc-2017-prelims-gs1-a-072","year":2017,"stage":"Prelims","paper":"Prelims GS-I","number":72,"booklet":"A","questionType":"MCQ","subject":"Economy","topic":"Soil Health Cards","question":"Consider the following statements:\\n\\nThe nation-wide ‘Soil Health Card Scheme’ aims at\\n\\n1. expanding the cultivable area under irrigation.\\n2. enabling the banks to assess the quantum of loans to be granted to farmers on the basis of soil quality.\\n3. checking the overuse of fertilizers in farmlands.\\n\\nWhich of the above statements is/are correct?","options":{"a":"1 and 2 only","b":"3 only","c":"2 and 3 only","d":"1, 2 and 3"},"answer":"b","keyStatus":"official","marks":2,"negativeMarks":0.6666666666666666,"wordLimit":0,"sourceUrl":"https://www.minimalistias.com/pyqs/prelims/2017","keyUrl":"https://lotusarise.com/wp-content/uploads/2021/12/UPSC-Prelims-Official-Answer-Key-2017-GS-1.pdf#page=1","page":0,"blocks":[{"type":"paragraph","text":"Consider the following statements:"},{"type":"paragraph","text":"The nation-wide ‘Soil Health Card Scheme’ aims at"},{"type":"paragraph","text":"1. expanding the cultivable area under irrigation.\\n2. enabling the banks to assess the quantum of loans to be granted to farmers on the basis of soil quality.\\n3. checking the overuse of fertilizers in farmlands."},{"type":"paragraph","text":"Which of the above statements is/are correct?"}],"sourceTitle":"UPSC CSE 2017 General Studies Paper I · Series A","explanation":{"justification":"Soil Health Cards identify nutrient status and recommend fertiliser use, helping prevent overuse. The scheme does not have expanding irrigation or providing bank-financed machinery as its stated aims.","concept":"Soil Health Cards","references":[{"title":"UPSC CSE2017 final key · SeriesA","url":"https://lotusarise.com/wp-content/uploads/2021/12/UPSC-Prelims-Official-Answer-Key-2017-GS-1.pdf#page=1"}]},"sourceNotes":"Editorial study note checked against the final key’s correct option; UPSC publishes the answer key, not these explanations."},{"id":"upsc-2017-prelims-gs1-a-073","year":2017,"stage":"Prelims","paper":"Prelims GS-I","number":73,"booklet":"A","questionType":"MCQ","subject":"Science & Technology","topic":"Chemicals in consumer products","question":"Consider the following pairs:\\n\\n | Commonly used / consumed materials | Unwanted or controversial chemicals likely to be found in them\\n1. | Lipstick | Lead\\n2. | Soft drinks | Brominated vegetable oils\\n3. | Chinese fast food | Monosodium glutamate\\n\\nWhich of the pairs given above is/are correctly matched?","options":{"a":"1 only","b":"2 and 3 only","c":"1 and 3 only","d":"1, 2 and 3"},"answer":"d","keyStatus":"official","marks":2,"negativeMarks":0.6666666666666666,"wordLimit":0,"sourceUrl":"https://www.minimalistias.com/pyqs/prelims/2017","keyUrl":"https://lotusarise.com/wp-content/uploads/2021/12/UPSC-Prelims-Official-Answer-Key-2017-GS-1.pdf#page=1","page":0,"blocks":[{"type":"paragraph","text":"Consider the following pairs:"},{"type":"table","headers":["No.","Commonly used / consumed materials","Unwanted or controversial chemicals likely to be found in them"],"rows":[["1.","Lipstick","Lead"],["2.","Soft drinks","Brominated vegetable oils"],["3.","Chinese fast food","Monosodium glutamate"]]},{"type":"paragraph","text":"Which of the pairs given above is/are correctly matched?"}],"sourceTitle":"UPSC CSE 2017 General Studies Paper I · Series A","explanation":{"justification":"All three are recognised associations: lead contamination in lipstick, brominated vegetable oil historically used in some soft drinks, and monosodium glutamate in some Chinese-style foods.","concept":"Chemicals in consumer products","references":[{"title":"UPSC CSE2017 final key · SeriesA","url":"https://lotusarise.com/wp-content/uploads/2021/12/UPSC-Prelims-Official-Answer-Key-2017-GS-1.pdf#page=1"}]},"sourceNotes":"Editorial study note checked against the final key’s correct option; UPSC publishes the answer key, not these explanations."},{"id":"upsc-2017-prelims-gs1-a-074","year":2017,"stage":"Prelims","paper":"Prelims GS-I","number":74,"booklet":"A","questionType":"MCQ","subject":"Science & Technology","topic":"Applied science & technology","question":"Organic Light Emitting Diodes (OLEDs) are used to create digital display in many devices. What are the advantages of OLED displays over Liquid Crystal displays?\\n\\n1. OLED displays can be fabricated on flexible plastic substrates.\\n2. Roll-up displays embedded in clothing can be made using OLEDs.\\n3. Transparent displays are possible using OLEDs.\\n\\nSelect the correct answer using the code given below:","options":{"a":"1 and 3 only","b":"2 only","c":"1, 2 and 3","d":"None of the above statements is correct"},"answer":"c","keyStatus":"official","marks":2,"negativeMarks":0.6666666666666666,"wordLimit":0,"sourceUrl":"https://www.minimalistias.com/pyqs/prelims/2017","keyUrl":"https://lotusarise.com/wp-content/uploads/2021/12/UPSC-Prelims-Official-Answer-Key-2017-GS-1.pdf#page=1","page":0,"blocks":[{"type":"paragraph","text":"Organic Light Emitting Diodes (OLEDs) are used to create digital display in many devices. What are the advantages of OLED displays over Liquid Crystal displays?"},{"type":"paragraph","text":"1. OLED displays can be fabricated on flexible plastic substrates.\\n2. Roll-up displays embedded in clothing can be made using OLEDs.\\n3. Transparent displays are possible using OLEDs."},{"type":"paragraph","text":"Select the correct answer using the code given below:"}],"sourceTitle":"UPSC CSE 2017 General Studies Paper I · Series A","explanation":{"justification":"OLEDs emit their own light and do not require a backlight like LCDs, allowing them to be fabricated on thin, flexible, or transparent substrates. This makes roll-up and transparent displays completely viable.","concept":"","references":[]},"sourceNotes":"Editorial study note matched by question wording and the final key’s correct-option wording; the UPSC final key controls scoring."},{"id":"upsc-2017-prelims-gs1-a-075","year":2017,"stage":"Prelims","paper":"Prelims GS-I","number":75,"booklet":"A","questionType":"MCQ","subject":"Art & Culture","topic":"Art, architecture & monuments","question":"Which of the following is/are famous for Sun temples?\\n\\n1. Arasavalli\\n2. Amarakantak\\n3. Omkareshwar\\n\\nSelect the correct answer using the code given below:","options":{"a":"1 only","b":"2 and 3 only","c":"1 and 3 only","d":"1, 2 and 3"},"answer":"a","keyStatus":"official","marks":2,"negativeMarks":0.6666666666666666,"wordLimit":0,"sourceUrl":"https://www.minimalistias.com/pyqs/prelims/2017","keyUrl":"https://lotusarise.com/wp-content/uploads/2021/12/UPSC-Prelims-Official-Answer-Key-2017-GS-1.pdf#page=1","page":0,"blocks":[{"type":"paragraph","text":"Which of the following is/are famous for Sun temples?"},{"type":"paragraph","text":"1. Arasavalli\\n2. Amarakantak\\n3. Omkareshwar"},{"type":"paragraph","text":"Select the correct answer using the code given below:"}],"sourceTitle":"UPSC CSE 2017 General Studies Paper I · Series A","explanation":{"justification":"Arasavalli in Srikakulam district of Andhra Pradesh is famous for the ancient Suryanarayana Swamy Temple (Sun Temple) built by 7th-century Kalinga ruler Devendra Varma. Amarkantak is known as the source of Narmada, and Omkareshwar is a Shaivite Jyotirlinga shrine.","concept":"","references":[]},"sourceNotes":"Editorial study note matched by question wording and the final key’s correct-option wording; the UPSC final key controls scoring."},{"id":"upsc-2017-prelims-gs1-a-076","year":2017,"stage":"Prelims","paper":"Prelims GS-I","number":76,"booklet":"A","questionType":"MCQ","subject":"Polity & Governance","topic":"Parliament & state legislatures","question":"Consider the following statements:\\n\\n1. In the election for Lok Sabha or State Assembly, the winning candidate must get at least 50 percent of the votes polled, to be declared elected.\\n2. According to the provisions laid down in the Constitution of India, in Lok Sabha, the Speaker’s post goes to the majority party and the Deputy Speaker’s to the Opposition.\\n\\nWhich of the statements given above is/are correct?","options":{"a":"1 only","b":"2 only","c":"Both 1 and 2","d":"Neither 1 nor 2"},"answer":"d","keyStatus":"official","marks":2,"negativeMarks":0.6666666666666666,"wordLimit":0,"sourceUrl":"https://www.minimalistias.com/pyqs/prelims/2017","keyUrl":"https://lotusarise.com/wp-content/uploads/2021/12/UPSC-Prelims-Official-Answer-Key-2017-GS-1.pdf#page=1","page":0,"blocks":[{"type":"paragraph","text":"Consider the following statements:"},{"type":"paragraph","text":"1. In the election for Lok Sabha or State Assembly, the winning candidate must get at least 50 percent of the votes polled, to be declared elected.\\n2. According to the provisions laid down in the Constitution of India, in Lok Sabha, the Speaker’s post goes to the majority party and the Deputy Speaker’s to the Opposition."},{"type":"paragraph","text":"Which of the statements given above is/are correct?"}],"sourceTitle":"UPSC CSE 2017 General Studies Paper I · Series A","explanation":{"justification":"India follows the First-Past-the-Post system, where a candidate only needs more votes than any other candidate, not necessarily 50% (Statement 1 is incorrect). The allocation of the Deputy Speaker post to the opposition is a convention, not a constitutional provision (Statement 2 is incorrect).","concept":"","references":[]},"sourceNotes":"Editorial study note matched by question wording and the final key’s correct-option wording; the UPSC final key controls scoring."},{"id":"upsc-2017-prelims-gs1-a-077","year":2017,"stage":"Prelims","paper":"Prelims GS-I","number":77,"booklet":"A","questionType":"MCQ","subject":"Economy","topic":"Economic liberalisation","question":"Which of the following has/have occurred in India after its liberalization of economic policies in 1991?\\n\\n1. Share of agriculture in GDP increased enormously.\\n2. Share of India’s exports in world trade increased.\\n3. FDI inflows increased.\\n4. India’s foreign exchange reserves increased enormously.\\n\\nSelect the correct answer using the codes given below:","options":{"a":"1 and 4 only","b":"2, 3 and 4 only","c":"2 and 3 only","d":"1, 2, 3 and 4"},"answer":"b","keyStatus":"official","marks":2,"negativeMarks":0.6666666666666666,"wordLimit":0,"sourceUrl":"https://www.minimalistias.com/pyqs/prelims/2017","keyUrl":"https://lotusarise.com/wp-content/uploads/2021/12/UPSC-Prelims-Official-Answer-Key-2017-GS-1.pdf#page=1","page":0,"blocks":[{"type":"paragraph","text":"Which of the following has/have occurred in India after its liberalization of economic policies in 1991?"},{"type":"paragraph","text":"1. Share of agriculture in GDP increased enormously.\\n2. Share of India’s exports in world trade increased.\\n3. FDI inflows increased.\\n4. India’s foreign exchange reserves increased enormously."},{"type":"paragraph","text":"Select the correct answer using the codes given below:"}],"sourceTitle":"UPSC CSE 2017 General Studies Paper I · Series A","explanation":{"justification":"After 1991, India’s export share, FDI inflows and foreign-exchange reserves increased. Agriculture’s share of GDP declined rather than rising enormously. Statements 2,3 and 4 are correct.","concept":"Economic liberalisation","references":[{"title":"UPSC CSE2017 final key · SeriesA","url":"https://lotusarise.com/wp-content/uploads/2021/12/UPSC-Prelims-Official-Answer-Key-2017-GS-1.pdf#page=1"}]},"sourceNotes":"Editorial study note checked against the final key’s correct option; UPSC publishes the answer key, not these explanations."},{"id":"upsc-2017-prelims-gs1-a-078","year":2017,"stage":"Prelims","paper":"Prelims GS-I","number":78,"booklet":"A","questionType":"MCQ","subject":"Science & Technology","topic":"Applied science & technology","question":"What is the application of Somatic Cell Nuclear Transfer Technology?","options":{"a":"Production of biolarvicides","b":"Manufacture of biodegradable plastics","c":"Reproductive cloning of animals","d":"Production of organisms free of diseases"},"answer":"c","keyStatus":"official","marks":2,"negativeMarks":0.6666666666666666,"wordLimit":0,"sourceUrl":"https://www.minimalistias.com/pyqs/prelims/2017","keyUrl":"https://lotusarise.com/wp-content/uploads/2021/12/UPSC-Prelims-Official-Answer-Key-2017-GS-1.pdf#page=1","page":0,"blocks":[{"type":"paragraph","text":"What is the application of Somatic Cell Nuclear Transfer Technology?"}],"sourceTitle":"UPSC CSE 2017 General Studies Paper I · Series A","explanation":{"justification":"Somatic cell nuclear transfer (SCNT) involves transferring the nucleus of a somatic cell into an enucleated egg cell. It is the exact reproductive technique used to create animal clones, such as Dolly the sheep.","concept":"","references":[]},"sourceNotes":"Editorial study note matched by question wording and the final key’s correct-option wording; the UPSC final key controls scoring."},{"id":"upsc-2017-prelims-gs1-a-079","year":2017,"stage":"Prelims","paper":"Prelims GS-I","number":79,"booklet":"A","questionType":"MCQ","subject":"Economy","topic":"Payments infrastructure","question":"Consider the following statements:\\n\\n1. National Payments Corporation of India (NPCI) helps in promoting the financial inclusion in the country.\\n2. NPCI has launched RuPay, a card payment scheme.\\n\\nWhich of the statements given above is/are correct?","options":{"a":"1 only","b":"2 only","c":"Both 1 and 2","d":"Neither 1 nor 2"},"answer":"c","keyStatus":"official","marks":2,"negativeMarks":0.6666666666666666,"wordLimit":0,"sourceUrl":"https://www.minimalistias.com/pyqs/prelims/2017","keyUrl":"https://lotusarise.com/wp-content/uploads/2021/12/UPSC-Prelims-Official-Answer-Key-2017-GS-1.pdf#page=1","page":0,"blocks":[{"type":"paragraph","text":"Consider the following statements:"},{"type":"paragraph","text":"1. National Payments Corporation of India (NPCI) helps in promoting the financial inclusion in the country.\\n2. NPCI has launched RuPay, a card payment scheme."},{"type":"paragraph","text":"Which of the statements given above is/are correct?"}],"sourceTitle":"UPSC CSE 2017 General Studies Paper I · Series A","explanation":{"justification":"NPCI supports inclusive payments systems and launched RuPay, India’s domestic card-payment network. Both statements are correct.","concept":"Payments infrastructure","references":[{"title":"UPSC CSE2017 final key · SeriesA","url":"https://lotusarise.com/wp-content/uploads/2021/12/UPSC-Prelims-Official-Answer-Key-2017-GS-1.pdf#page=1"}]},"sourceNotes":"Editorial study note checked against the final key’s correct option; UPSC publishes the answer key, not these explanations."},{"id":"upsc-2017-prelims-gs1-a-080","year":2017,"stage":"Prelims","paper":"Prelims GS-I","number":80,"booklet":"A","questionType":"MCQ","subject":"Environment","topic":"Tiger monitoring","question":"The term ‘M-STrIPES’ is sometimes seen in the news in the context of","options":{"a":"Captive breeding of Wild Fauna","b":"Maintenance of Tiger Reserves","c":"Indigenous Satellite Navigation System","d":"Security of National Highways"},"answer":"b","keyStatus":"official","marks":2,"negativeMarks":0.6666666666666666,"wordLimit":0,"sourceUrl":"https://www.minimalistias.com/pyqs/prelims/2017","keyUrl":"https://lotusarise.com/wp-content/uploads/2021/12/UPSC-Prelims-Official-Answer-Key-2017-GS-1.pdf#page=1","page":0,"blocks":[{"type":"paragraph","text":"The term ‘M-STrIPES’ is sometimes seen in the news in the context of"}],"sourceTitle":"UPSC CSE 2017 General Studies Paper I · Series A","explanation":{"justification":"M-STrIPES stands for Monitoring System for Tigers – Intensive Protection and Ecological Status. It supports patrols, ecological monitoring and management in tiger reserves.","concept":"Tiger monitoring","references":[{"title":"UPSC CSE2017 final key · SeriesA","url":"https://lotusarise.com/wp-content/uploads/2021/12/UPSC-Prelims-Official-Answer-Key-2017-GS-1.pdf#page=1"}]},"sourceNotes":"Editorial study note checked against the final key’s correct option; UPSC publishes the answer key, not these explanations."},{"id":"upsc-2017-prelims-gs1-a-081","year":2017,"stage":"Prelims","paper":"Prelims GS-I","number":81,"booklet":"A","questionType":"MCQ","subject":"Economy","topic":"Public finance & fiscal policy","question":"What is/are the most likely advantages of implementing ‘Goods and Services Tax (GST)’?\\n\\n1. It will replace multiple taxes collected by multiple authorities and will thus create a single market in India.\\n2. It will drastically reduce the ‘Current Account Deficit’ of India and will enable it to increase its foreign exchange reserves.\\n3. It will enormously increase the growth and size of economy of India and will enable it to overtake China in the near future.\\n\\nSelect the correct answer using the code given below:","options":{"a":"1 only","b":"2 and 3 only","c":"1 and 3 only","d":"1, 2 and 3"},"answer":"a","keyStatus":"official","marks":2,"negativeMarks":0.6666666666666666,"wordLimit":0,"sourceUrl":"https://www.minimalistias.com/pyqs/prelims/2017","keyUrl":"https://lotusarise.com/wp-content/uploads/2021/12/UPSC-Prelims-Official-Answer-Key-2017-GS-1.pdf#page=1","page":0,"blocks":[{"type":"paragraph","text":"What is/are the most likely advantages of implementing ‘Goods and Services Tax (GST)’?"},{"type":"paragraph","text":"1. It will replace multiple taxes collected by multiple authorities and will thus create a single market in India.\\n2. It will drastically reduce the ‘Current Account Deficit’ of India and will enable it to increase its foreign exchange reserves.\\n3. It will enormously increase the growth and size of economy of India and will enable it to overtake China in the near future."},{"type":"paragraph","text":"Select the correct answer using the code given below:"}],"sourceTitle":"UPSC CSE 2017 General Studies Paper I · Series A","explanation":{"justification":"GST subsumes multiple indirect taxes levied by central and state governments to establish a unified common national market. Claims that it will drastically slash the Current Account Deficit or guarantee overtaking China's economy are exaggerated and lack direct correlation.","concept":"","references":[]},"sourceNotes":"Editorial study note matched by question wording and the final key’s correct-option wording; the UPSC final key controls scoring."},{"id":"upsc-2017-prelims-gs1-a-082","year":2017,"stage":"Prelims","paper":"Prelims GS-I","number":82,"booklet":"A","questionType":"MCQ","subject":"International Relations","topic":"India-EU trade","question":"‘Broad-based Trade and Investment Agreement (BTIA)’ is sometimes seen in the news in the context of negotiations held between India and","options":{"a":"European Union","b":"Gulf Cooperation Council","c":"Organization for Economic Cooperation and Development","d":"Shanghai Cooperation Organization"},"answer":"a","keyStatus":"official","marks":2,"negativeMarks":0.6666666666666666,"wordLimit":0,"sourceUrl":"https://www.minimalistias.com/pyqs/prelims/2017","keyUrl":"https://lotusarise.com/wp-content/uploads/2021/12/UPSC-Prelims-Official-Answer-Key-2017-GS-1.pdf#page=1","page":0,"blocks":[{"type":"paragraph","text":"‘Broad-based Trade and Investment Agreement (BTIA)’ is sometimes seen in the news in the context of negotiations held between India and"}],"sourceTitle":"UPSC CSE 2017 General Studies Paper I · Series A","explanation":{"justification":"The Broad-based Trade and Investment Agreement refers to negotiations between India and the European Union for a comprehensive trade and investment arrangement.","concept":"India-EU trade","references":[{"title":"UPSC CSE2017 final key · SeriesA","url":"https://lotusarise.com/wp-content/uploads/2021/12/UPSC-Prelims-Official-Answer-Key-2017-GS-1.pdf#page=1"}]},"sourceNotes":"Editorial study note checked against the final key’s correct option; UPSC publishes the answer key, not these explanations."},{"id":"upsc-2017-prelims-gs1-a-083","year":2017,"stage":"Prelims","paper":"Prelims GS-I","number":83,"booklet":"A","questionType":"MCQ","subject":"International Relations","topic":"WTO Trade Facilitation Agreement","question":"Consider the following statements:\\n\\n1. India has ratified the Trade Facilitation Agreement (TFA) of WTO.\\n2. TFA is a part of WTO’s Bali Ministerial Package of 2013.\\n3. TFA came into force in January 2016.\\n\\nWhich of the statements given above is/are correct?","options":{"a":"1 and 2 only","b":"1 and 3 only","c":"2 and 3 only","d":"1, 2 and 3"},"answer":"a","keyStatus":"official","marks":2,"negativeMarks":0.6666666666666666,"wordLimit":0,"sourceUrl":"https://www.minimalistias.com/pyqs/prelims/2017","keyUrl":"https://lotusarise.com/wp-content/uploads/2021/12/UPSC-Prelims-Official-Answer-Key-2017-GS-1.pdf#page=1","page":0,"blocks":[{"type":"paragraph","text":"Consider the following statements:"},{"type":"paragraph","text":"1. India has ratified the Trade Facilitation Agreement (TFA) of WTO.\\n2. TFA is a part of WTO’s Bali Ministerial Package of 2013.\\n3. TFA came into force in January 2016."},{"type":"paragraph","text":"Which of the statements given above is/are correct?"}],"sourceTitle":"UPSC CSE 2017 General Studies Paper I · Series A","explanation":{"justification":"The TFA formed part of the 2013 Bali package and India ratified it in 2016. It entered into force on 22 February 2017, not January 2016, so statements 1 and 2 are correct.","concept":"WTO Trade Facilitation Agreement","references":[{"title":"UPSC CSE2017 final key · SeriesA","url":"https://lotusarise.com/wp-content/uploads/2021/12/UPSC-Prelims-Official-Answer-Key-2017-GS-1.pdf#page=1"}]},"sourceNotes":"Editorial study note checked against the final key’s correct option; UPSC publishes the answer key, not these explanations."},{"id":"upsc-2017-prelims-gs1-a-084","year":2017,"stage":"Prelims","paper":"Prelims GS-I","number":84,"booklet":"A","questionType":"MCQ","subject":"International Relations","topic":"Chabahar Port","question":"What is the importance of developing Chabahar Port by India?","options":{"a":"India’s trade with African countries will enormously increase.","b":"India’s relations with oil-producing Arab countries will be strengthened.","c":"India will not depend on Pakistan for access to Afghanistan and Central Asia.","d":"Pakistan will facilitate and protect the installation of a gas pipeline between Iraq and India."},"answer":"c","keyStatus":"official","marks":2,"negativeMarks":0.6666666666666666,"wordLimit":0,"sourceUrl":"https://www.minimalistias.com/pyqs/prelims/2017","keyUrl":"https://lotusarise.com/wp-content/uploads/2021/12/UPSC-Prelims-Official-Answer-Key-2017-GS-1.pdf#page=1","page":0,"blocks":[{"type":"paragraph","text":"What is the importance of developing Chabahar Port by India?"}],"sourceTitle":"UPSC CSE 2017 General Studies Paper I · Series A","explanation":{"justification":"Chabahar provides India a route through Iran toward Afghanistan and Central Asia, avoiding reliance on transit through Pakistan. This is its strategic connectivity value.","concept":"Chabahar Port","references":[{"title":"UPSC CSE2017 final key · SeriesA","url":"https://lotusarise.com/wp-content/uploads/2021/12/UPSC-Prelims-Official-Answer-Key-2017-GS-1.pdf#page=1"}]},"sourceNotes":"Editorial study note checked against the final key’s correct option; UPSC publishes the answer key, not these explanations."},{"id":"upsc-2017-prelims-gs1-a-085","year":2017,"stage":"Prelims","paper":"Prelims GS-I","number":85,"booklet":"A","questionType":"MCQ","subject":"Science & Technology","topic":"Applied science & technology","question":"In India, it is legally mandatory for which of the following to report on cyber security incidents?\\n\\n1. Service providers\\n2. Data centres\\n3. Body corporate\\n\\nSelect the correct answer using the code given below:","options":{"a":"1 only","b":"1 and 2 only","c":"3 only","d":"1, 2 and 3"},"answer":"d","keyStatus":"official","marks":2,"negativeMarks":0.6666666666666666,"wordLimit":0,"sourceUrl":"https://www.minimalistias.com/pyqs/prelims/2017","keyUrl":"https://lotusarise.com/wp-content/uploads/2021/12/UPSC-Prelims-Official-Answer-Key-2017-GS-1.pdf#page=1","page":0,"blocks":[{"type":"paragraph","text":"In India, it is legally mandatory for which of the following to report on cyber security incidents?"},{"type":"paragraph","text":"1. Service providers\\n2. Data centres\\n3. Body corporate"},{"type":"paragraph","text":"Select the correct answer using the code given below:"}],"sourceTitle":"UPSC CSE 2017 General Studies Paper I · Series A","explanation":{"justification":"As per the directives issued by CERT-In under the IT Act, it is mandatory for all service providers, intermediaries, data centers, and body corporates to swiftly report cyber security incidents.","concept":"","references":[]},"sourceNotes":"Editorial study note matched by question wording and the final key’s correct-option wording; the UPSC final key controls scoring."},{"id":"upsc-2017-prelims-gs1-a-086","year":2017,"stage":"Prelims","paper":"Prelims GS-I","number":86,"booklet":"A","questionType":"MCQ","subject":"Polity & Governance","topic":"Rights, duties & directive principles","question":"Right to vote and to be elected in India is a","options":{"a":"Fundamental Right","b":"Natural Right","c":"Constitutional Right","d":"Legal Right"},"answer":"c","keyStatus":"official","marks":2,"negativeMarks":0.6666666666666666,"wordLimit":0,"sourceUrl":"https://www.minimalistias.com/pyqs/prelims/2017","keyUrl":"https://lotusarise.com/wp-content/uploads/2021/12/UPSC-Prelims-Official-Answer-Key-2017-GS-1.pdf#page=1","page":0,"blocks":[{"type":"paragraph","text":"Right to vote and to be elected in India is a"}],"sourceTitle":"UPSC CSE 2017 General Studies Paper I · Series A","explanation":{"justification":"The right to vote has been recognised under Article 326 of the Indian Constitution, making it a Constitutional Right based on adult suffrage.","concept":"","references":[]},"sourceNotes":"Editorial study note matched by question wording and the final key’s correct-option wording; the UPSC final key controls scoring."},{"id":"upsc-2017-prelims-gs1-a-087","year":2017,"stage":"Prelims","paper":"Prelims GS-I","number":87,"booklet":"A","questionType":"MCQ","subject":"Science & Technology","topic":"Applied science & technology","question":"What is the purpose of ‘evolved Laser Interferometer Space Antenna (eLISA)’ project?","options":{"a":"To detect neutrinos","b":"To detect gravitational waves","c":"To detect the effectiveness of missile defence system","d":"To study the effect of solar flares on our communication systems"},"answer":"b","keyStatus":"official","marks":2,"negativeMarks":0.6666666666666666,"wordLimit":0,"sourceUrl":"https://www.minimalistias.com/pyqs/prelims/2017","keyUrl":"https://lotusarise.com/wp-content/uploads/2021/12/UPSC-Prelims-Official-Answer-Key-2017-GS-1.pdf#page=1","page":0,"blocks":[{"type":"paragraph","text":"What is the purpose of ‘evolved Laser Interferometer Space Antenna (eLISA)’ project?"}],"sourceTitle":"UPSC CSE 2017 General Studies Paper I · Series A","explanation":{"justification":"The eLISA is a European Space Agency mission designed to detect and accurately measure gravitational waves using a constellation of spacecraft.","concept":"","references":[]},"sourceNotes":"Editorial study note matched by question wording and the final key’s correct-option wording; the UPSC final key controls scoring."},{"id":"upsc-2017-prelims-gs1-a-088","year":2017,"stage":"Prelims","paper":"Prelims GS-I","number":88,"booklet":"A","questionType":"MCQ","subject":"Social Development","topic":"Vidyanjali","question":"What is the purpose of ‘Vidyanjali Yojana’?\\n\\n1. To enable the famous foreign educational institutions to open their campuses in India.\\n2. To increase the quality of education provided in government schools by taking help from the private sector and the community.\\n3. To encourage voluntary monetary contributions from private individuals and organizations so as to improve the infrastructure facilities for primary and secondary schools.\\n\\nSelect the correct answer using the code given below:","options":{"a":"2 only","b":"3 only","c":"1 and 2 only","d":"2 and 3 only"},"answer":"a","keyStatus":"official","marks":2,"negativeMarks":0.6666666666666666,"wordLimit":0,"sourceUrl":"https://www.minimalistias.com/pyqs/prelims/2017","keyUrl":"https://lotusarise.com/wp-content/uploads/2021/12/UPSC-Prelims-Official-Answer-Key-2017-GS-1.pdf#page=1","page":0,"blocks":[{"type":"paragraph","text":"What is the purpose of ‘Vidyanjali Yojana’?"},{"type":"paragraph","text":"1. To enable the famous foreign educational institutions to open their campuses in India.\\n2. To increase the quality of education provided in government schools by taking help from the private sector and the community.\\n3. To encourage voluntary monetary contributions from private individuals and organizations so as to improve the infrastructure facilities for primary and secondary schools."},{"type":"paragraph","text":"Select the correct answer using the code given below:"}],"sourceTitle":"UPSC CSE 2017 General Studies Paper I · Series A","explanation":{"justification":"The original Vidyanjali initiative brought volunteers and community expertise into government schools to support children’s learning. It was not a foreign-campus programme or the monetary-donation scheme described here.","concept":"Vidyanjali","references":[{"title":"UPSC CSE2017 final key · SeriesA","url":"https://lotusarise.com/wp-content/uploads/2021/12/UPSC-Prelims-Official-Answer-Key-2017-GS-1.pdf#page=1"}]},"sourceNotes":"Editorial study note checked against the final key’s correct option; UPSC publishes the answer key, not these explanations."},{"id":"upsc-2017-prelims-gs1-a-089","year":2017,"stage":"Prelims","paper":"Prelims GS-I","number":89,"booklet":"A","questionType":"MCQ","subject":"Social Development","topic":"Unnat Bharat Abhiyan","question":"What is the aim of the programme ‘Unnat Bharat Abhiyan’?","options":{"a":"Achieving 100% literacy by promoting collaboration between voluntary organizations and government’s education system and local communities.","b":"Connecting institutions of higher education with local communities to address development challenges through appropriate technologies.","c":"Strengthening India’s scientific research institutions in order to make India a scientific and technological power.","d":"Developing human capital by allocating special funds for health care and education of rural and urban poor, and organizing skill development programmes and vocational training for them."},"answer":"b","keyStatus":"official","marks":2,"negativeMarks":0.6666666666666666,"wordLimit":0,"sourceUrl":"https://www.minimalistias.com/pyqs/prelims/2017","keyUrl":"https://lotusarise.com/wp-content/uploads/2021/12/UPSC-Prelims-Official-Answer-Key-2017-GS-1.pdf#page=1","page":0,"blocks":[{"type":"paragraph","text":"What is the aim of the programme ‘Unnat Bharat Abhiyan’?"}],"sourceTitle":"UPSC CSE 2017 General Studies Paper I · Series A","explanation":{"justification":"Unnat Bharat Abhiyan connects higher-education institutions with rural communities to identify development needs and apply suitable knowledge and technologies to address them.","concept":"Unnat Bharat Abhiyan","references":[{"title":"UPSC CSE2017 final key · SeriesA","url":"https://lotusarise.com/wp-content/uploads/2021/12/UPSC-Prelims-Official-Answer-Key-2017-GS-1.pdf#page=1"}]},"sourceNotes":"Editorial study note checked against the final key’s correct option; UPSC publishes the answer key, not these explanations."},{"id":"upsc-2017-prelims-gs1-a-090","year":2017,"stage":"Prelims","paper":"Prelims GS-I","number":90,"booklet":"A","questionType":"MCQ","subject":"Polity & Governance","topic":"Organisations & miscellaneous polity","question":"Consider the following statements:\\n\\n1. The Election Commission of India is a five-member body.\\n2. Union Ministry of Home Affairs decides the election schedule for the conduct of both general elections and bye-elections.\\n3. Election Commission resolves the disputes relating to splits/mergers of recognised political parties.\\n\\nWhich of the statements given above is/are correct?","options":{"a":"1 and 2 only","b":"2 only","c":"2 and 3 only","d":"3 only"},"answer":"d","keyStatus":"official","marks":2,"negativeMarks":0.6666666666666666,"wordLimit":0,"sourceUrl":"https://www.minimalistias.com/pyqs/prelims/2017","keyUrl":"https://lotusarise.com/wp-content/uploads/2021/12/UPSC-Prelims-Official-Answer-Key-2017-GS-1.pdf#page=1","page":0,"blocks":[{"type":"paragraph","text":"Consider the following statements:"},{"type":"paragraph","text":"1. The Election Commission of India is a five-member body.\\n2. Union Ministry of Home Affairs decides the election schedule for the conduct of both general elections and bye-elections.\\n3. Election Commission resolves the disputes relating to splits/mergers of recognised political parties."},{"type":"paragraph","text":"Which of the statements given above is/are correct?"}],"sourceTitle":"UPSC CSE 2017 General Studies Paper I · Series A","explanation":{"justification":"The Election Commission is a three-member body, not five (1 is incorrect). The Election Commission, not the Home Ministry, decides the election schedule (2 is incorrect). The EC resolves disputes relating to splits/mergers of recognized parties (3 is correct).","concept":"","references":[]},"sourceNotes":"Editorial study note matched by question wording and the final key’s correct-option wording; the UPSC final key controls scoring."},{"id":"upsc-2017-prelims-gs1-a-091","year":2017,"stage":"Prelims","paper":"Prelims GS-I","number":91,"booklet":"A","questionType":"MCQ","subject":"Environment","topic":"Wildlife schedules","question":"In India, if a species of tortoise is declared protected under Schedule I of the Wildlife (Protection) Act, 1972, what does it imply?","options":{"a":"It enjoys the same level of protection as the tiger.","b":"It no longer exists in the wild, a few individuals are under captive protection; and now it is impossible to prevent its extinction.","c":"It is endemic to a particular region of India.","d":"Both (b) and (c) stated above are correct in this context."},"answer":"a","keyStatus":"official","marks":2,"negativeMarks":0.6666666666666666,"wordLimit":0,"sourceUrl":"https://www.minimalistias.com/pyqs/prelims/2017","keyUrl":"https://lotusarise.com/wp-content/uploads/2021/12/UPSC-Prelims-Official-Answer-Key-2017-GS-1.pdf#page=1","page":0,"blocks":[{"type":"paragraph","text":"In India, if a species of tortoise is declared protected under Schedule I of the Wildlife (Protection) Act, 1972, what does it imply?"}],"sourceTitle":"UPSC CSE 2017 General Studies Paper I · Series A","explanation":{"justification":"ScheduleI protection is the highest protection category under the law relevant to this paper. A tortoise placed in that schedule receives the same statutory level of protection as a tiger.","concept":"Wildlife schedules","references":[{"title":"UPSC CSE2017 final key · SeriesA","url":"https://lotusarise.com/wp-content/uploads/2021/12/UPSC-Prelims-Official-Answer-Key-2017-GS-1.pdf#page=1"}]},"sourceNotes":"Editorial study note checked against the final key’s correct option; UPSC publishes the answer key, not these explanations."},{"id":"upsc-2017-prelims-gs1-a-092","year":2017,"stage":"Prelims","paper":"Prelims GS-I","number":92,"booklet":"A","questionType":"MCQ","subject":"Polity & Governance","topic":"Judiciary","question":"In India, Judicial Review implies","options":{"a":"the power of the Judiciary to pronounce upon the constitutionality of laws and executive orders.","b":"the power of the Judiciary to question the wisdom of the laws enacted by the Legislatures.","c":"the power of the Judiciary to review all the legislative enactments before they are assented to by the President.","d":"the power of the Judiciary to review its own judgements given earlier in similar or different cases."},"answer":"a","keyStatus":"official","marks":2,"negativeMarks":0.6666666666666666,"wordLimit":0,"sourceUrl":"https://www.minimalistias.com/pyqs/prelims/2017","keyUrl":"https://lotusarise.com/wp-content/uploads/2021/12/UPSC-Prelims-Official-Answer-Key-2017-GS-1.pdf#page=1","page":0,"blocks":[{"type":"paragraph","text":"In India, Judicial Review implies"}],"sourceTitle":"UPSC CSE 2017 General Studies Paper I · Series A","explanation":{"justification":"Judicial review is the power of the judiciary to examine the constitutionality of legislative enactments and executive orders of both Central and State governments to check if they violate the Constitution.","concept":"","references":[]},"sourceNotes":"Editorial study note matched by question wording and the final key’s correct-option wording; the UPSC final key controls scoring."},{"id":"upsc-2017-prelims-gs1-a-093","year":2017,"stage":"Prelims","paper":"Prelims GS-I","number":93,"booklet":"A","questionType":"MCQ","subject":"History","topic":"Modern India · Gandhian & mass movements","question":"With reference to Indian freedom struggle, consider the following events:\\n\\n1. Mutiny in Royal Indian Navy\\n2. Quit India Movement launched\\n3. Second Round Table Conference\\n\\nWhat is the correct chronological sequence of the above events?","options":{"a":"1-2-3","b":"2-1-3","c":"3-2-1","d":"3-1-2"},"answer":"c","keyStatus":"official","marks":2,"negativeMarks":0.6666666666666666,"wordLimit":0,"sourceUrl":"https://www.minimalistias.com/pyqs/prelims/2017","keyUrl":"https://lotusarise.com/wp-content/uploads/2021/12/UPSC-Prelims-Official-Answer-Key-2017-GS-1.pdf#page=1","page":0,"blocks":[{"type":"paragraph","text":"With reference to Indian freedom struggle, consider the following events:"},{"type":"paragraph","text":"1. Mutiny in Royal Indian Navy\\n2. Quit India Movement launched\\n3. Second Round Table Conference"},{"type":"paragraph","text":"What is the correct chronological sequence of the above events?"}],"sourceTitle":"UPSC CSE 2017 General Studies Paper I · Series A","explanation":{"justification":"The correct chronological order is: Second Round Table Conference (1931), Quit India Movement (1942), and the Mutiny in the Royal Indian Navy (1946).","concept":"","references":[]},"sourceNotes":"Editorial study note matched by question wording and the final key’s correct-option wording; the UPSC final key controls scoring."},{"id":"upsc-2017-prelims-gs1-a-094","year":2017,"stage":"Prelims","paper":"Prelims GS-I","number":94,"booklet":"A","questionType":"MCQ","subject":"Economy","topic":"Public finance & fiscal policy","question":"Consider the following statements:\\n\\n1. Tax revenue as a percent of GDP of India has steadily increased in the last decade.\\n2. Fiscal deficit as a percent of GDP of India has steadily increased in the last decade.\\n\\nWhich of the statements given above is/are correct?","options":{"a":"1 only","b":"2 only","c":"Both 1 and 2","d":"Neither 1 nor 2"},"answer":"d","keyStatus":"official","marks":2,"negativeMarks":0.6666666666666666,"wordLimit":0,"sourceUrl":"https://www.minimalistias.com/pyqs/prelims/2017","keyUrl":"https://lotusarise.com/wp-content/uploads/2021/12/UPSC-Prelims-Official-Answer-Key-2017-GS-1.pdf#page=1","page":0,"blocks":[{"type":"paragraph","text":"Consider the following statements:"},{"type":"paragraph","text":"1. Tax revenue as a percent of GDP of India has steadily increased in the last decade.\\n2. Fiscal deficit as a percent of GDP of India has steadily increased in the last decade."},{"type":"paragraph","text":"Which of the statements given above is/are correct?"}],"sourceTitle":"UPSC CSE 2017 General Studies Paper I · Series A","explanation":{"justification":"Neither statement is correct because both tax revenue-to-GDP ratio and fiscal deficit-to-GDP ratio experienced fluctuating trends over the decade rather than a steady, continuous increase.","concept":"","references":[]},"sourceNotes":"Editorial study note matched by question wording and the final key’s correct-option wording; the UPSC final key controls scoring."},{"id":"upsc-2017-prelims-gs1-a-095","year":2017,"stage":"Prelims","paper":"Prelims GS-I","number":95,"booklet":"A","questionType":"MCQ","subject":"Environment","topic":"Asiatic lion conservation","question":"Recently there was a proposal to translocate some of the lions from their natural habitat in Gujarat to which one of the following sites?","options":{"a":"Corbett National Park","b":"Kuno Palpur Wildlife Sanctuary","c":"Mudumalai Wildlife Sanctuary","d":"Sariska National Park"},"answer":"b","keyStatus":"official","marks":2,"negativeMarks":0.6666666666666666,"wordLimit":0,"sourceUrl":"https://www.minimalistias.com/pyqs/prelims/2017","keyUrl":"https://lotusarise.com/wp-content/uploads/2021/12/UPSC-Prelims-Official-Answer-Key-2017-GS-1.pdf#page=1","page":0,"blocks":[{"type":"paragraph","text":"Recently there was a proposal to translocate some of the lions from their natural habitat in Gujarat to which one of the following sites?"}],"sourceTitle":"UPSC CSE 2017 General Studies Paper I · Series A","explanation":{"justification":"Kuno Palpur in Madhya Pradesh was the identified site for establishing another wild Asiatic-lion population outside Gujarat. The proposed translocation aimed to reduce risks to a single population.","concept":"Asiatic lion conservation","references":[{"title":"UPSC CSE2017 final key · SeriesA","url":"https://lotusarise.com/wp-content/uploads/2021/12/UPSC-Prelims-Official-Answer-Key-2017-GS-1.pdf#page=1"}]},"sourceNotes":"Editorial study note checked against the final key’s correct option; UPSC publishes the answer key, not these explanations."},{"id":"upsc-2017-prelims-gs1-a-096","year":2017,"stage":"Prelims","paper":"Prelims GS-I","number":96,"booklet":"A","questionType":"MCQ","subject":"Polity & Governance","topic":"Rights, duties & directive principles","question":"Which of the following are not necessarily the consequences of the proclamation of the President’s rule in a State?\\n\\n1. Dissolution of the State Legislative Assembly\\n2. Removal of the Council of Ministers in the State\\n3. Dissolution of the local bodies\\n\\nSelect the correct answer using the code given below:","options":{"a":"1 and 2 only","b":"1 and 3 only","c":"2 and 3 only","d":"1, 2 and 3"},"answer":"b","keyStatus":"official","marks":2,"negativeMarks":0.6666666666666666,"wordLimit":0,"sourceUrl":"https://www.minimalistias.com/pyqs/prelims/2017","keyUrl":"https://lotusarise.com/wp-content/uploads/2021/12/UPSC-Prelims-Official-Answer-Key-2017-GS-1.pdf#page=1","page":0,"blocks":[{"type":"paragraph","text":"Which of the following are not necessarily the consequences of the proclamation of the President’s rule in a State?"},{"type":"paragraph","text":"1. Dissolution of the State Legislative Assembly\\n2. Removal of the Council of Ministers in the State\\n3. Dissolution of the local bodies"},{"type":"paragraph","text":"Select the correct answer using the code given below:"}],"sourceTitle":"UPSC CSE 2017 General Studies Paper I · Series A","explanation":{"justification":"When President's Rule is imposed, the President dismisses the Council of Ministers. However, the dissolution of the State Legislative Assembly and local bodies is not necessarily a consequence.","concept":"","references":[]},"sourceNotes":"Editorial study note matched by question wording and the final key’s correct-option wording; the UPSC final key controls scoring."},{"id":"upsc-2017-prelims-gs1-a-097","year":2017,"stage":"Prelims","paper":"Prelims GS-I","number":97,"booklet":"A","questionType":"MCQ","subject":"Polity & Governance","topic":"Rights, duties & directive principles","question":"Which of the following are envisaged by the Right against Exploitation in the Constitution of India?\\n\\n1. Prohibition of traffic in human beings and forced labour\\n2. Abolition of untouchability\\n3. Protection of the interests of minorities\\n4. Prohibition of employment of children in factories and mines\\n\\nSelect the correct answer using the code given below:","options":{"a":"1, 2 and 4 only","b":"2, 3 and 4 only","c":"1 and 4 only","d":"1, 2, 3 and 4"},"answer":"c","keyStatus":"official","marks":2,"negativeMarks":0.6666666666666666,"wordLimit":0,"sourceUrl":"https://www.minimalistias.com/pyqs/prelims/2017","keyUrl":"https://lotusarise.com/wp-content/uploads/2021/12/UPSC-Prelims-Official-Answer-Key-2017-GS-1.pdf#page=1","page":0,"blocks":[{"type":"paragraph","text":"Which of the following are envisaged by the Right against Exploitation in the Constitution of India?"},{"type":"paragraph","text":"1. Prohibition of traffic in human beings and forced labour\\n2. Abolition of untouchability\\n3. Protection of the interests of minorities\\n4. Prohibition of employment of children in factories and mines"},{"type":"paragraph","text":"Select the correct answer using the code given below:"}],"sourceTitle":"UPSC CSE 2017 General Studies Paper I · Series A","explanation":{"justification":"The Right against Exploitation includes Article 23 (prohibiting human trafficking and forced labour) and Article 24 (prohibiting child labour). Untouchability and minority rights fall under different categories.","concept":"","references":[]},"sourceNotes":"Editorial study note matched by question wording and the final key’s correct-option wording; the UPSC final key controls scoring."},{"id":"upsc-2017-prelims-gs1-a-098","year":2017,"stage":"Prelims","paper":"Prelims GS-I","number":98,"booklet":"A","questionType":"MCQ","subject":"Geography","topic":"Andaman and Nicobar Islands","question":"Which of the following is geographically closest to Great Nicobar?","options":{"a":"Sumatra","b":"Borneo","c":"Java","d":"Sri Lanka"},"answer":"a","keyStatus":"official","marks":2,"negativeMarks":0.6666666666666666,"wordLimit":0,"sourceUrl":"https://www.minimalistias.com/pyqs/prelims/2017","keyUrl":"https://lotusarise.com/wp-content/uploads/2021/12/UPSC-Prelims-Official-Answer-Key-2017-GS-1.pdf#page=1","page":0,"blocks":[{"type":"paragraph","text":"Which of the following is geographically closest to Great Nicobar?"}],"sourceTitle":"UPSC CSE 2017 General Studies Paper I · Series A","explanation":{"justification":"Sumatra lies south of Great Nicobar across the Great Channel. It is the nearest of these islands to Great Nicobar; Borneo, Java and Sri Lanka are farther away.","concept":"Andaman and Nicobar Islands","references":[{"title":"UPSC CSE2017 final key · SeriesA","url":"https://lotusarise.com/wp-content/uploads/2021/12/UPSC-Prelims-Official-Answer-Key-2017-GS-1.pdf#page=1"},{"title":"Nicobar district: Location and area","url":"https://db.and.nic.in/nicobars/Profile/LocArea.php"}]},"sourceNotes":"Editorial study note checked against the final key’s correct option; UPSC publishes the answer key, not these explanations."},{"id":"upsc-2017-prelims-gs1-a-099","year":2017,"stage":"Prelims","paper":"Prelims GS-I","number":99,"booklet":"A","questionType":"MCQ","subject":"Polity & Governance","topic":"Parliament & state legislatures","question":"Out of the following statements, choose the one that brings out the principle underlying the Cabinet form of Government:","options":{"a":"An arrangement for minimizing the criticism against the Government whose responsibilities are complex and hard to carry out to the satisfaction of all.","b":"A mechanism for speeding up the activities of the Government whose responsibilities are increasing day by day.","c":"A mechanism of parliamentary democracy for ensuring collective responsibility of the Government to the people.","d":"A device for strengthening the hands of the head of the Government whose hold over the people is in a state of decline."},"answer":"c","keyStatus":"official","marks":2,"negativeMarks":0.6666666666666666,"wordLimit":0,"sourceUrl":"https://www.minimalistias.com/pyqs/prelims/2017","keyUrl":"https://lotusarise.com/wp-content/uploads/2021/12/UPSC-Prelims-Official-Answer-Key-2017-GS-1.pdf#page=1","page":0,"blocks":[{"type":"paragraph","text":"Out of the following statements, choose the one that brings out the principle underlying the Cabinet form of Government:"}],"sourceTitle":"UPSC CSE 2017 General Studies Paper I · Series A","explanation":{"justification":"Parliamentary democracy envisages a cabinet form of government where the executive (Council of Ministers) is collectively responsible to the legislature (House of the People), thus ensuring collective responsibility of the Government to the people.","concept":"","references":[]},"sourceNotes":"Editorial study note matched by question wording and the final key’s correct-option wording; the UPSC final key controls scoring."},{"id":"upsc-2017-prelims-gs1-a-100","year":2017,"stage":"Prelims","paper":"Prelims GS-I","number":100,"booklet":"A","questionType":"MCQ","subject":"Polity & Governance","topic":"Indian federalism","question":"Which one of the following is not a feature of Indian federalism?","options":{"a":"There is an independent judiciary in India.","b":"Powers have been clearly divided between the Centre and the States.","c":"The federating units have been given unequal representation in the Rajya Sabha.","d":"It is the result of an agreement among the federating units."},"answer":"d","keyStatus":"official","marks":2,"negativeMarks":0.6666666666666666,"wordLimit":0,"sourceUrl":"https://www.minimalistias.com/pyqs/prelims/2017","keyUrl":"https://lotusarise.com/wp-content/uploads/2021/12/UPSC-Prelims-Official-Answer-Key-2017-GS-1.pdf#page=1","page":0,"blocks":[{"type":"paragraph","text":"Which one of the following is not a feature of Indian federalism?"}],"sourceTitle":"UPSC CSE 2017 General Studies Paper I · Series A","explanation":{"justification":"Indian federalism was created by the Constitution rather than a compact among previously sovereign federating units. The statement about an agreement among units is therefore not an Indian feature.","concept":"Indian federalism","references":[{"title":"UPSC CSE2017 final key · SeriesA","url":"https://lotusarise.com/wp-content/uploads/2021/12/UPSC-Prelims-Official-Answer-Key-2017-GS-1.pdf#page=1"}]},"sourceNotes":"Editorial study note checked against the final key’s correct option; UPSC publishes the answer key, not these explanations."}]`);export{e as p};
